import type { ChoiceQuestion, LessonSection, OntleedLesson, TypeQuestion } from './types';

// Keep feedback paired with its option while varying the correct position reproducibly.
const rotate = <T,>(items: T[], offset: number): T[] => [...items.slice(offset), ...items.slice(0, offset)];
const offsetFor = (id: string, count: number): number => [...id].reduce((sum, char) => sum + char.charCodeAt(0), 0) % count;
const c = (id: string, prompt: string, sentence: string, options: string[], answer: number, feedback: string[], concept: string, hint: string, explanation: string): ChoiceQuestion => {
  const offset = offsetFor(id, options.length);
  return { id, kind: 'choice', prompt, sentence, options: rotate(options, offset), answer: (answer - offset + options.length) % options.length, feedback: rotate(feedback, offset), concept, hint, explanation };
};
const t = (id: string, prompt: string, sentence: string, accept: string[], concept: string, hint: string, explanation: string): TypeQuestion => ({ id, kind: 'type', prompt, sentence, accept, concept, hint, explanation });
const s = (title: string, paragraphs: string[], examples: { sentence: string; analysis: string }[], pitfall: string, takeaway: string): LessonSection => ({ title, paragraphs, examples, pitfall, takeaway });

